-- SHORT questions
INSERT INTO questions (question, type, class_id, subject_id, chapter_id, teacher_id, correct_answer) VALUES
('মূলদ সংখ্যা কাকে বলে? উদাহরণ দাও।', 'short', 6, 22, 16, '6abe3ed6-df14-47f7-9217-56382499ddeb', 'যে সংখ্যাকে $\frac{p}{q}$ আকারে প্রকাশ করা যায় (যেখানে $p, q$ পূর্ণ সংখ্যা, $q \neq 0$), তাকে মূলদ সংখ্যা বলে। যেমন: $\frac{3}{4}, 0.5, -2$'),
('$\sqrt{2}$ যে অমূলদ সংখ্যা তা প্রমাণ করো।', 'short', 6, 22, 16, '6abe3ed6-df14-47f7-9217-56382499ddeb', 'ধরি $\sqrt{2}$ মূলদ, তাহলে $\sqrt{2} = \frac{p}{q}$। বর্গ করলে $2 = \frac{p^2}{q^2}$ অর্থাৎ $p^2 = 2q^2$। এতে $p$ জোড়। $p = 2k$ ধরলে $4k^2 = 2q^2$, $q^2 = 2k^2$, $q$ও জোড়। দুইটিই জোড় হলে $\frac{p}{q}$ লঘিষ্ঠ নয়—দ্বন্দ্ব। তাই $\sqrt{2}$ অমূলদ।'),
('সূচকের নিয়মগুলো লেখো।', 'short', 6, 22, 17, '6abe3ed6-df14-47f7-9217-56382499ddeb', '$a^m \times a^n = a^{m+n}$, $\frac{a^m}{a^n} = a^{m-n}$, $(a^m)^n = a^{mn}$, $a^0 = 1$, $a^{-n} = \frac{1}{a^n}$'),
('$\log_{10} 1000$ এর মান নির্ণয় করো।', 'short', 6, 22, 17, '6abe3ed6-df14-47f7-9217-56382499ddeb', '$\log_{10} 1000 = \log_{10} 10^3 = 3$'),
('লগারিদমের সংজ্ঞা লেখো।', 'short', 6, 22, 17, '6abe3ed6-df14-47f7-9217-56382499ddeb', 'যদি $a^x = N$ হয়, তবে $x = \log_a N$। এখানে $a$ ভিত্তি ($a > 0, a \neq 1$), $N > 0$।');

-- CREATIVE questions (using creative_data JSONB)
INSERT INTO questions (question, type, class_id, subject_id, chapter_id, teacher_id, creative_data) VALUES
('একটি শ্রেণীকক্ষে ৩০ জন শিক্ষার্থী আছে। তাদের মধ্যে ১৮ জন গণিত পছন্দ করে, ১২ জন বিজ্ঞান পছন্দ করে এবং ৬ জন উভয়ই পছন্দ করে।', 'cq', 6, 22, 16, '6abe3ed6-df14-47f7-9217-56382499ddeb',
'{"stem": "একটি শ্রেণীকক্ষে ৩০ জন শিক্ষার্থী আছে। তাদের মধ্যে ১৮ জন গণিত পছন্দ করে, ১২ জন বিজ্ঞান পছন্দ করে এবং ৬ জন উভয়ই পছন্দ করে।", "parts": [{"label": "ক", "question": "মূলদ সংখ্যার সংজ্ঞা দাও।", "answer": "যে সংখ্যাকে p/q আকারে প্রকাশ করা যায়, তাকে মূলদ সংখ্যা বলে।"}, {"label": "খ", "question": "সেটের ভেন চিত্র অঙ্কন করো।", "answer": "দুইটি ছেদকৃত বৃত্ত দ্বারা ভেন চিত্র আঁকতে হবে।"}, {"label": "গ", "question": "কতজন শিক্ষার্থী কেবল গণিত পছন্দ করে তা নির্ণয় করো।", "answer": "কেবল গণিত = ১৮ - ৬ = ১২ জন"}, {"label": "ঘ", "question": "কতজন শিক্ষার্থী কোনোটিই পছন্দ করে না তা বিশ্লেষণ করো।", "answer": "কোনোটিই পছন্দ করে না = ৩০ - (১৮ + ১২ - ৬) = ৬ জন"}]}'::jsonb),

('রহিম $2^x = 32$ সমীকরণটি সমাধান করতে চায়। সে লগারিদমের সাহায্যে এটি সমাধান করার সিদ্ধান্ত নিল।', 'cq', 6, 22, 17, '6abe3ed6-df14-47f7-9217-56382499ddeb',
'{"stem": "রহিম $2^x = 32$ সমীকরণটি সমাধান করতে চায়। সে লগারিদমের সাহায্যে এটি সমাধান করার সিদ্ধান্ত নিল।", "parts": [{"label": "ক", "question": "লগারিদমের সংজ্ঞা দাও।", "answer": "যদি $a^x = N$ হয়, তবে $x = \\log_a N$"}, {"label": "খ", "question": "$2^x = 32$ থেকে $x$ এর মান নির্ণয় করো।", "answer": "$32 = 2^5$, তাই $x = 5$"}, {"label": "গ", "question": "$\\log_2 32 + \\log_2 8$ এর মান নির্ণয় করো।", "answer": "$\\log_2 32 + \\log_2 8 = 5 + 3 = 8$"}, {"label": "ঘ", "question": "লগারিদমের নিয়ম ব্যবহার করে $\\log_2 256$ নির্ণয় করো এবং যাচাই করো।", "answer": "$256 = 2^8$, তাই $\\log_2 256 = 8$। যাচাই: $2^8 = 256$ ✓"}]}'::jsonb);

