INSERT INTO questions (question, type, class_id, subject_id, chapter_id, teacher_id, correct_answer) VALUES
('সমবেগ ও অসমবেগের মধ্যে পার্থক্য লেখো।', 'short', 5, 17, 12, '6abe3ed6-df14-47f7-9217-56382499ddeb', 'সমবেগে বস্তু সমান সময়ে সমান দূরত্ব অতিক্রম করে এবং দিক অপরিবর্তিত থাকে। অসমবেগে দূরত্ব বা দিক পরিবর্তন হয়।'),
