('ঘর্ষণ বল কী? এর প্রকারভেদ লেখো।', 'short', 5, 17, 13, '6abe3ed6-df14-47f7-9217-56382499ddeb', 'দুটি তলের মধ্যে আপেক্ষিক গতি বা গতির প্রবণতার বিরুদ্ধে যে বল কাজ করে তাকে ঘর্ষণ বল বলে। প্রকারভেদ: স্থিতি ঘর্ষণ, গতি ঘর্ষণ, আবর্ত ঘর্ষণ।');

INSERT INTO questions (question, type, class_id, subject_id, chapter_id, teacher_id, creative_data) VALUES
('করিম ৫ কেজি ভরের একটি বস্তুকে ২০ নিউটন বল প্রয়োগ করে ঠেলছে। মেঝে ও বস্তুর মধ্যে ঘর্ষণ বল ৫ নিউটন।', 'cq', 5, 17, 13, '6abe3ed6-df14-47f7-9217-56382499ddeb',
'{"stem": "করিম ৫ কেজি ভরের একটি বস্তুকে ২০ নিউটন বল প্রয়োগ করে ঠেলছে। মেঝে ও বস্তুর মধ্যে ঘর্ষণ বল ৫ নিউটন।", "parts": [{"label": "ক", "question": "নিউটনের দ্বিতীয় সূত্র বিবৃত করো।", "answer": "বস্তুর ভরবেগের পরিবর্তনের হার প্রযুক্ত বলের সমানুপাতিক।"}, {"label": "খ", "question": "নিট বল নির্ণয় করো।", "answer": "নিট বল = ২০ - ৫ = ১৫ নিউটন"}, {"label": "গ", "question": "বস্তুটির ত্বরণ নির্ণয় করো।", "answer": "$a = F/m = 15/5 = 3$ m/s²"}, {"label": "ঘ", "question": "৪ সেকেন্ড পর বস্তুটির বেগ ও অতিক্রান্ত দূরত্ব নির্ণয় করো।", "answer": "$v = u + at = 0 + 3 \\times 4 = 12$ m/s, $s = \\frac{1}{2}at^2 = \\frac{1}{2} \\times 3 \\times 16 = 24$ m"}]}'::jsonb);

