INSERT INTO questions (question, type, class_id, subject_id, chapter_id, teacher_id, correct_answer) VALUES
('সেট কাকে বলে? রোস্টার ও সেট-বিল্ডার পদ্ধতি উদাহরণসহ লেখো।', 'short', 5, 16, 8, '6abe3ed6-df14-47f7-9217-56382499ddeb', 'সুসংজ্ঞায়িত বস্তুর সমষ্টিকে সেট বলে। রোস্টার: $A = \{1,2,3\}$। সেট-বিল্ডার: $A = \{x : x \in \mathbb{N}, x < 4\}$'),
('$(a+b)^2$ সূত্রটি প্রমাণ করো।', 'short', 5, 16, 9, '6abe3ed6-df14-47f7-9217-56382499ddeb', '$(a+b)^2 = (a+b)(a+b) = a^2 + ab + ba + b^2 = a^2 + 2ab + b^2$');

